          .filter(([c]) => c === "watcher")
          .map(([, l]) => JSON.parse(l) as { kind?: string; data?: { tools?: unknown[]; count?: number } });
      const said = toWatcher().filter((g) => g.kind === "tools");
      expect(said.at(-1)?.data?.count).toBe(1);
