1	import { describe, expect, it } from "vitest";
2	import { notifier, type Attached, type LiveStore, type Poster, type Watcher } from "../lib/handlers/live";
3	import { hashToken } from "../lib/handlers/auth";
4	import { route, type WsDeps, type WsEvent } from "../lib/handlers/ws";
5	import type { Race } from "../lib/handlers/races";
6	import type { Ask, SessionMember, SessionMeta } from "../lib/handlers/store";
7	
8	/**
9	 * The socket is a doorbell: it carries a "changed" and nothing else. What
10	 * it must get right is who may ring it and who hears it. A stranger
11	 * cannot open one, a member cannot watch a session they are not in, and a
12	 * connection that has gone is cleaned up the first time it is missed.
13	 */
14	
15	function memoryLive(): LiveStore & { conns: Map<string, string>; watches: Map<string, Set<string>>; marks: Map<string, Attached> } {
16	  const conns = new Map<string, string>();
17	  const watches = new Map<string, Set<string>>();
18	  const marks = new Map<string, Attached>();
19	  return {
20	    conns,
21	    watches,
22	    marks,
23	    async connect(id, sub, _at, attached) {
24	      conns.set(id, sub);
25	      if (attached) marks.set(id, attached);
26	    },
27	    async connection(id) {
28	      const sub = conns.get(id);
29	      return sub ? { sub, ...(marks.get(id) ?? {}) } : null;
30	    },
31	    async watch(id, sessionId, _sub, _at, attached) {
32	      if (!watches.has(sessionId)) watches.set(sessionId, new Set());
33	      watches.get(sessionId)!.add(id);
34	      if (attached) marks.set(id, attached);
35	    },
36	    async watchers(sessionId): Promise<Watcher[]> {
37	      return [...(watches.get(sessionId) ?? [])].map((connectionId) => ({
38	        connectionId,
39	        sub: conns.get(connectionId) ?? "",
40	        ...(marks.get(connectionId) ?? {}),
41	      }));
42	    },
43	    async decksOf(sub) {
44	      return [...conns.entries()]
45	        .filter(([id, s]) => s === sub && marks.get(id)?.deck === true)
46	        .map(([connectionId]) => ({ connectionId, ...(marks.get(connectionId) ?? {}) }));
47	    },
48	    async disconnect(id) {
49	      conns.delete(id);
50	      marks.delete(id);
51	      for (const set of watches.values()) set.delete(id);
52	    },
53	  };
54	}
55	
56	const meta = (id: string, ownerSub: string): SessionMeta => ({
57	  id,
58	  packId: "p",
59	  packVersion: "1",
60	  ownerSub,
61	  createdAt: "",
62	  updatedAt: "",
63	  seq: 3,
64	});
65	const member = (sub: string): SessionMember => ({ sub, role: "player", joinedAt: "" });
66	
67	/** Every ask the socket raised, for the tests that care. */
68	const asked: Ask[] = [];
69	/** Every session patch the socket wrote, for the tests that care. */
70	const patched: Array<[string, Record<string, unknown>]> = [];
71	
72	function deps(live = memoryLive()): WsDeps & { live: ReturnType<typeof memoryLive> } {
73	  asked.length = 0;
74	  patched.length = 0;
75	  return {
76	    live,
77	    store: {
78	      async getSnapshot() {
79	        return null;
80	      },
81	      async addAsk(_id, ask) {
82	        asked.push(ask);
83	        return asked;
84	      },
85	      async streamKeyOwner(hash) {
86	        if (hash === hashToken("watchkey")) return { sub: "user_1", kind: "watch" as const };
87	        if (hash === hashToken("presskey")) return { sub: "user_1", kind: "press" as const };
88	        return null;
89	      },
90	      async manifest(sub) {
91	        // s1 is named and titled, for the deck's picker; s2 has neither
92	        // and stands in for a run nobody happens to have open.
93	        const owned = sub === "user_1" ? ["open", "shared", "s1", "s2"] : [];
94	        const extra: Record<string, { name?: string; packTitle?: string }> = {
95	          s1: { name: "Thursday", packTitle: "The Long Kiln" },
96	        };
97	        return {
98	          packs: [],
99	          licenses: [],
100	          sessions: owned.map((id) => ({
101	            id,
102	            role: "owner" as const,
103	            packId: "p",
104	            packVersion: "1",
105	            ownerSub: sub,
106	            updatedAt: id === "open" ? "2026-09-11T00:10:00Z" : "2026-09-11T00:00:00Z",
107	            seq: 3,
108	            ...extra[id],
109	          })),
110	        };
111	      },
112	      async updateSession(id, _at, patch) {
113	        patched.push([id, patch]);
114	        return null;
115	      },
116	      async getSession(id) {
117	        if (id === "asking")
118	          return {
119	            meta: { ...meta(id, "user_1"), publicTokenHash: hashToken("livetok"), askPolicy: "ask" as const },
120	            members: [member("user_1")],
121	          };
122	        if (id === "open") return { meta: { ...meta(id, "user_1"), publicTokenHash: hashToken("livetok") }, members: [member("user_1")] };
123	        if (id === "shared") return { meta: meta(id, "user_1"), members: [member("user_1"), member("user_2")] };
124	        if (id === "s1") return { meta: { ...meta(id, "user_1"), packTitle: "The Long Kiln" }, members: [member("user_1")] };
125	        if (id === "private") return { meta: meta(id, "user_9"), members: [member("user_9")] };
126	        return null;
127	      },
128	    },
129	    races: {
130	      async getRace(id): Promise<Race | null> {
131	        if (id === "race1")
132	          return {
133	            meta: {
134	              id,
135	              code: "ABCDEF",
136	              packId: "p",
137	              packVersion: "1",
138	              mode: "race",
139	              seed: "s",
140	              ownerSub: "user_1",
141	              createdAt: "",
142	              updatedAt: "",
143	              seq: 1,
144	            },
145	            entries: [{ sub: "user_1", joinedAt: "" }],
146	          };
147	        if (id === "race2")
148	          return {
149	            meta: {
150	              id,
151	              code: "GHJKLM",
152	              packId: "p",
153	              packVersion: "1",
154	              mode: "race",
155	              seed: "s",
156	              ownerSub: "user_9",
157	              createdAt: "",
158	              updatedAt: "",
159	              seq: 1,
160	            },
161	            entries: [{ sub: "user_9", joinedAt: "" }],
162	          };
163	        return null;
164	      },
165	    },
166	    verify: async (authorization) => {
167	      if (authorization === "Bearer good") return { sub: "user_1", sid: "s1" };
168	      throw new Error("bad token");
169	    },
170	    now: () => "2026-09-06T12:00:00.000Z",
171	  };
172	}
173	
174	const ev = (routeKey: string, connectionId: string, extra: Partial<WsEvent> = {}): WsEvent => ({
175	  requestContext: { routeKey, connectionId },
176	  ...extra,
177	});
178	
179	describe("opening a socket", () => {
180	  it("takes the token from the query string and refuses a bad one before the socket opens", async () => {
181	    const d = deps();
182	    expect((await route(ev("$connect", "c1", { queryStringParameters: { token: "good" } }), d)).statusCode).toBe(200);
183	    expect(d.live.conns.get("c1")).toBe("user_1");
184	    expect((await route(ev("$connect", "c2", { queryStringParameters: { token: "bad" } }), d)).statusCode).toBe(401);
185	    expect((await route(ev("$connect", "c3"), d)).statusCode).toBe(401);
186	    expect(d.live.conns.has("c2")).toBe(false);
187	  });
188	});
